async def q(code, filters):
    r = await call_boto3(service_name='pricing', operation_name='GetProducts', region_name='us-east-1', params={'ServiceCode':code,'Filters':[{'Type':'TERM_MATCH','Field':k,'Value':v} for k,v in filters.items()],'MaxResults':100})
