            d=json.loads(x) if isinstance(x,str) else x
            a=d['product']['attributes']
            for t in d['terms'].get('OnDemand',{}).values():
                for pd in t['priceDimensions'].values():
                    out.append((a.get('usagetype'),pd['description'][:70],pd['beginRange'],pd['endRange'],pd['pricePerUnit'].get('USD'),pd['unit']))
        tok=r.get('NextToken')
        if not tok:break
    return out
