    while True:
        f=[{'Type':'TERM_MATCH','Field':'regionCode','Value':reg}]+[{'Type':'TERM_MATCH','Field':k,'Value':v} for k,v in extra.items()]
        p={'ServiceCode':code,'Filters':f,'MaxResults':100}
        if tok:p['NextToken']=tok
        r=await call_boto3(service_name='pricing',operation_name='GetProducts',region_name='us-east-1',params=p)
        for x in r.get('PriceList',[]):
            d=json.loads(x) if isinstance(x,str) else x
            a=d['product']['attributes']
            for t in d['terms'].get('OnDemand',{}).values():
                for pd in t['priceDimensions'].values():
                    out.append((a.get('usagetype','').split('-',1)[-1],pd['description'][:75],pd['beginRange'],pd['pricePerUnit'].get('USD'),pd['unit']))
        tok=r.get('NextToken')
        if not tok:break
    return sorted(set(out))
for reg in ['us-east-1','ap-southeast-1']:
    print('## CWL',reg)
    for fam in ['Data Payload','Storage Snapshot','Logs']:
        try:
            for r in await q('AmazonCloudWatch',reg,{'productFamily':fam}): 
                if float(r[3])>0: print(r)
        except Exception as e: print(fam,str(e)[:100])
    print('## AOSS',reg)
    try:
        for r in await q('AmazonES',reg,{'productFamily':'Amazon OpenSearch Service Serverless'}): print(r)
    except Exception as e: print(str(e)[:100])
    for r in (await q('AmazonES',reg,{})):
        if re.search('Serverless|OCU|Ocu',r[0]+r[1]): print(r)

